from pathlib import Path
import base64, subprocess, tempfile, zlib

patch = zlib.decompress(base64.b64decode("""""")).decode("utf-8")

with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False) as f:
    f.write(patch)
    patch_path=f.name

subprocess.run(["patch", "-p1", "--forward", "--batch", "-i", patch_path], check=True)

source = Path("index.html").read_text(encoding="utf-8")
for marker in ['data-build="ma-project-v88"', 'id="dockContextBar"', 'contextualDockTabForPart', 'mobileContextSheetOpen']:
    if marker not in source:
        raise SystemExit(f"missing v88 marker: {marker}")
for forbidden in ["v82 / image-button system", "original Sketch Craft image buttons", "btn-normal.png"]:
    if forbidden in source:
        raise SystemExit(f"forbidden image-button residue: {forbidden}")
